-- ===================== 圣焰隐修院 (Priory of the Sacred Flame) =====================
addon.GuideData.versions["11.0"]["圣焰隐修院"] = {
    ["戴尔克莱上尉"] = { order = 1, type = "BOSS", tips = "{rt8}戴尔克莱上尉{rt8}||{rt1}必断[战斗狂啸]{rt1}(自身与全场友方增伤)；分散躲[碎地之矛]直线，实际范围比视觉大||被[野蛮重殴]按住的人由队友集火余烬爪解救；T对[贯穿护甲]流血易伤开减伤，治疗及时驱散" },
    ["布朗派克男爵"] = { order = 2, type = "BOSS", tips = "{rt8}布朗派克男爵{rt8}||{rt1}必断[灼烧之光]{rt1}(全团伤害且给BOSS回血)；能量满[报偿之怒]强化所有法术，减伤铺满||集合放[谴罚者之盾]落点，出圈后跟T统一换位躲[谴罚者爆破]；[献祭葬火]光球一个一个轮流去撞，别同时吃给治疗爆压" },
    ["隐修院长穆普雷"] = { order = 3, type = "BOSS", tips = "{rt8}隐修院长穆普雷{rt8}||尽量断[神圣惩击]；躲[神圣烈焰]火柱与残留[神圣之地]，被点名追踪立刻跑开别穿人||[盲目之光]背对BOSS并开减伤防迷惑；[心灵之火]期间治疗爆发||50%上二楼开[圣光屏障]，全爆发破盾后{rt1}必断[拥抱圣光]{rt1}；[阿拉希新兵]无仇恨，聚到一侧减速风筝，靠[非凡力量]自损血耗死" },
    ["卫队长苏雷曼"] = { order = 4, type = "MOB", tips = "{rt8}卫队长苏雷曼{rt8}||场地中央小BOSS，击杀后引出[歇尼麦尔中士]；亲信卫士互相靠近有[人多势众](每名+200%伤害)，务必逐个分开引杀" },
    ["歇尼麦尔中士"] = { order = 5, type = "MOB", tips = "{rt8}歇尼麦尔中士{rt8}||躲[跃进打击]落点，T对[蛮力重击]开减伤；单独引出来打，绝不能和其他亲信卫士叠在一起" },
    ["高阶牧师艾姆雅"] = { order = 6, type = "MOB", tips = "{rt8}高阶牧师艾姆雅{rt8}||{rt1}必断[神圣惩击]{rt1}；击杀后引出[泰纳·杜尔玛]" },
    ["泰纳·杜尔玛"] = { order = 7, type = "MOB", tips = "{rt8}泰纳·杜尔玛{rt8}||{rt1}必断[火球术]与[余烬冲击]{rt1}；躲[余烬风暴]地板" },
    ["锻造大师达米安"] = { order = 8, type = "MOB", tips = "{rt8}锻造大师达米安{rt8}||北侧小BOSS，击杀后引出[艾蕾娜·安博兰兹]；打掉2名亲信卫士后戴尔克莱会带最后1名一起出来" },
    ["艾蕾娜·安博兰兹"] = { order = 9, type = "MOB", tips = "{rt8}艾蕾娜·安博兰兹{rt8}||[圣光烁辉]增益可驱散/法术偷取；躲[神圣审判]点名地板" },
    ["虔诚的牧师"] = { order = 10, type = "MOB", tips = "{rt8}虔诚的牧师{rt8}||{rt1}必断[神圣惩击]{rt1}(高额单体)；常多只同时出现，务必分好打断链" },
    ["狂热圣殿骑士"] = { order = 11, type = "MOB", tips = "{rt8}狂热圣殿骑士{rt8}||[光怒圣印]主要威胁坦克，T开减伤；有偷取/进攻驱散就拆[圣殿骑士之怒]增益，别站[奉献]地板" },
    ["光明之魂"] = { order = 12, type = "MOB", tips = "{rt8}光明之魂{rt8}||残血会读[光明爆发]给周围敌方回血，T提前把其他怪拉开或直接控断" },
}

-- ===================== 驭雷栖巢 (The Rookery) =====================
addon.GuideData.versions["11.0"]["驭雷栖巢"] = {
    ["凯里欧斯"] = { order = 1, type = "BOSS", tips = "{rt8}凯里欧斯{rt8}||P1全员8码以上分散躲[崩解闪电]圈，[狂野闪电]沿直线朝人打，左右侧移即可||满能量飞到中央放[闪电涌流]：4道射线顺/逆时针扫场，看BOSS身上发光点判起始方位，全队贴一起同向绕圈并躲[定身雷矢]小圈||结束时[闪电疾冲]落地大圈躲开；被定身可驱散" },
    ["雷卫戈伦"] = { order = 2, type = "BOSS", tips = "{rt8}雷卫戈伦{rt8}||核心[混沌腐蚀]：4层虚空点名，结束跳给最近的人并炸6码；接过的人立刻远离，{rt1}身上带[混沌脆弱]绝不能再接{rt1}(受伤+300%)||[黑暗引力]拉人，引导完8码内爆炸击退，读条结束前往外跑||[粉碎现实]跳人后延伸[现实裂痕]并留2分钟[徘徊虚空]，尽量把水放场边" },
    ["虚空石畸体"] = { order = 3, type = "BOSS", tips = "{rt8}虚空石畸体{rt8}||T与近战左、治疗中、远程右分开站；[释放腐蚀]DOT驱散后地上留[渗透腐蚀]黑水且会扩大，别放在BOSS脚下||[虚无颠覆]召出[虚空碎块]，被标[驭雷者电荷]的人用圈罩住引爆，别让它[重塑]成[觉醒的虚空石]||破[虚空壳壁]后沃克玛尔[风暴复仇]昏迷并使其受伤+100%，全爆发；近战位必须有人否则触发[熵灭]，躲[湮灭波]直线" },
    ["军需官科拉泰特"] = { order = 4, type = "MOB", tips = "{rt8}军需官科拉泰特{rt8}||站侧面，头前召的球别吃且会往后收；[熵能护盾]期间别打正面(会偏转)，绕后输出" },
    ["被诅咒的雷霆使"] = { order = 5, type = "MOB", tips = "{rt8}被诅咒的雷霆使{rt8}||{rt1}必断[闪电箭]{rt1}；两发连点又没减伤基本必倒，有该怪的波次务必分好打断链" },
    ["诅咒的雷鸫守卫"] = { order = 6, type = "MOB", tips = "{rt8}诅咒的雷鸫守卫{rt8}||自带急速增益，可驱散/法术偷取，否则攻速与伤害飙升" },
    ["驭虚者"] = { order = 7, type = "MOB", tips = "{rt8}驭虚者{rt8}||躲十字形地板；[局部风暴]对全队持续中量AOE，治疗提前铺血，近战减伤" },
    ["凝虚散播者"] = { order = 8, type = "MOB", tips = "{rt8}凝虚散播者{rt8}||[诱集暗影]把全队拉入漩涡持续掉血，第一时间往外跑；[弧形虚空]点名大圈别套队友，开减伤" },
    ["被腐化的先知"] = { order = 9, type = "MOB", tips = "{rt8}被腐化的先知{rt8}||{rt1}必断[虚空箭]{rt1}；治疗及时驱散[渗流腐化]" },
    ["虚咒碾压者"] = { order = 10, type = "MOB", tips = "{rt8}虚咒碾压者{rt8}||会点名跳人，起跳瞬间后跳或卡束缚可规避；叠减疗debuff，优先控制击杀" },
}

-- ===================== 燧酿酒庄 (Cinderbrew Meadery) =====================
addon.GuideData.versions["11.0"]["燧酿酒庄"] = {
    ["酿造大师阿德里尔"] = { order = 1, type = "BOSS", tips = "{rt8}酿造大师阿德里尔{rt8}||躲头前[炽热响嗝]锥形(会转向随机玩家)；被[投掷燧酿]点名有明显轨迹，第一时间跑开，别把[滚烫蜜糖]留在近战位||66%/33%进[欢乐时光]，BOSS吃[不屑一顾]减伤99%：DPS一人搬一杯、T搬两杯喂[口渴的主顾]止住[吵闹喧哗]||T对[醉酿投]开减伤防被击飞进毒水；史诗结束时爆[横行乱斗]，别乱站否则昏迷" },
    ["艾帕"] = { order = 2, type = "BOSS", tips = "{rt8}艾帕{rt8}||{rt1}[喷涌佳酿]生成的[酒滴]必须第一时间控住并秒掉{rt1}，让它触到BOSS会触发[满上](全团大AOE+20%最大生命护盾)||[燃烧发酵]高额火DOT可驱散，没驱到就开减伤；T对[干杯勾拳]减伤防击退||酒滴死后留[泛涌蜂蜜]，极其考验T带位，持续把BOSS往干净地面拉，别拉墙边" },
    ["本克·鸣蜂"] = { order = 3, type = "BOSS", tips = "{rt8}本克·鸣蜂{rt8}||[点心时间]召出蜂蜜桶后，{rt1}击杀[贪婪的燧烬蜂]并骑上去用[蜂驰电掣!]撞掉所有桶{rt1}，漏桶会灭团||T被[蜂蜜料汁]点名把烈焰蜜池放场边；蜜蜂第一时间拉出水，死在水里的等它复活飞出来再杀||[工蜂]的[碎肉针刺]流血叠层高了要减伤或直接破咒" },
    ["戈尔迪·底爵"] = { order = 4, type = "BOSS", tips = "{rt8}戈尔迪·底爵{rt8}||场上刷大火药桶与小桶：T用头前[点钞打炮](永远锁T)点爆大桶，DPS点名火圈补消，{rt1}优先消大桶{rt1}||满能量[遮天蔽日!]引爆场上剩余全部桶+全团AOE，务必减伤，且T要把BOSS带离桶边防瞬秒||每次桶炸后十字形火浪四散，及时躲；[燧火创伤]超过1层开减伤" },
    ["风险投资公司纵火狂"] = { order = 5, type = "MOB", tips = "{rt8}风险投资公司纵火狂{rt8}||{rt1}必断[沸燃烈焰]{rt1}；[迸发地狱火]点名火DOT优先驱散，没驱就开减伤" },
    ["风味科学家"] = { order = 6, type = "MOB", tips = "{rt8}风味科学家{rt8}||{rt1}必断[疗愈蜂蜜]{rt1}(可法术偷取)；{rt1}[失败批次]召唤物10秒读条成功即全团大AOE，立刻集火秒掉{rt1}" },
    ["品尝师"] = { order = 7, type = "MOB", tips = "{rt8}品尝师{rt8}||{rt1}必断[免费样品?]{rt1}；身上的激怒效果可驱散" },
    ["蜜蜂驯养师"] = { order = 8, type = "MOB", tips = "{rt8}蜜蜂驯养师{rt8}||{rt1}必断[狂蜂怒火]{rt1}" },
    ["皇家果酱供应商"] = { order = 9, type = "MOB", tips = "{rt8}皇家果酱供应商{rt8}||{rt1}必断[蜂蜜齐射]{rt1}" },
    ["雇佣打手"] = { order = 10, type = "MOB", tips = "{rt8}雇佣打手{rt8}||[投掷椅子]点名高额物理，被点名前保持满血并备好大减伤" },
    ["风险公司蜂蜜采集者"] = { order = 11, type = "MOB", tips = "{rt8}风险公司蜂蜜采集者{rt8}||[蜂拥惊喜]每次施放伤害递增，尽量控断并速杀；25%以下的大蜜蜂会放[绝命尖刺]，控断或减伤" },
    ["粗心的酒花大地精"] = { order = 12, type = "MOB", tips = "{rt8}粗心的酒花大地精{rt8}||通道大怪：拉在离墙不远不近处让它撞墙，冲太远会ADD；躲开[冲锋]路径" },
}

-- ===================== 暗焰裂口 (Darkflame Cleft) =====================
addon.GuideData.versions["11.0"]["暗焰裂口"] = {
    ["老蜡须"] = { order = 1, type = "BOSS", tips = "{rt8}老蜡须{rt8}||别站铁轨；铁轨发亮/[卑鄙轨术]时{rt1}第一时间转火黄名炸药矿车{rt1}，[高速碰撞]顺手清[卑微的劳工]||[鲁莽冲锋]点最远的人，保持人-BOSS-附近墙柱三点一线让它撞短，躲路径并防随后的[塌方点]落石(击飞+落石易连杀)||被[诱引烛焰]点名会被所有劳工追，控制加减伤风筝；T对[穿岩凿](+25%物理易伤)开减伤" },
    ["布雷炙孔"] = { order = 2, type = "BOSS", tips = "{rt8}布雷炙孔{rt8}||核心是蜡烛：点亮越多环境AOE越低。被[点芯弹幕]点名者立刻跑到场边，用脚下火圈尽量多点燃蜡烛(每人约2根)，起手先点蜡烛再开爆发||[灭火强风]/[吹灭之息]引到场边只吹灭1根，留一块干净落脚地；[燃焰地狱火]重新点燃全部蜡烛并沿路径打伤害，提前开减伤||躲[点燃]蔓延的余烬；近战范围必须有人否则触发[炽烈风暴]" },
    ["蜡烛之王"] = { order = 3, type = "BOSS", tips = "{rt8}蜡烛之王{rt8}||[诡谀铸模]给每人造蜡像，场上蜡像越多全团AOE越高，每轮务必清完：全队小范围集合放像||单体[暗焰之锄]箭头点名时，站到落单蜡像后面借穿透击碎它；群体[投掷暗焰]圈尽量罩住多个蜡像||{rt1}必断[偏执失心]{rt1}(恐惧，读条极频繁)；被[投掷暗焰]点名开减伤，治疗全程持续抬血" },
    ["黑暗之主"] = { order = 4, type = "BOSS", tips = "{rt8}黑暗之主{rt8}||{rt1}必须站在[烛光]范围内输出{rt1}，黑暗中伤害与治疗被大幅削弱；治疗忙不过来时其他人帮忙搬小蜡烛给大蜡烛充能||被点名紫圈跑出人群加减伤，顺手带一支小蜡烛回来补能，别用圈套住队友或蜡烛||T扛起蜡烛躲开头前[幽影斩击]，别让它扫掉蜡烛掉能量||{rt1}秒断[召唤暗嗣]与暗嗣的[吸取光明]{rt1}；[永恒黑暗]全团AOE开减伤" },
    ["狗头人履职者"] = { order = 5, type = "MOB", tips = "{rt8}狗头人履职者{rt8}||{rt1}控断[梆!]{rt1}(昏迷3秒，晕在火圈里基本暴毙)；躲开它放的小黄圈" },
    ["点芯者"] = { order = 6, type = "MOB", tips = "{rt8}点芯者{rt8}||{rt1}必断[点芯箭]{rt1}；读条极频繁，和[梆!]一起排好打断链" },
    ["鼹鼠倌"] = { order = 7, type = "MOB", tips = "{rt8}鼹鼠倌{rt8}||{rt1}优先击杀并断[鼹鼠狂暴]{rt1}；大狗头人的击飞会把小怪打散导致ADD，T把整波拉到墙角聚拢" },
    ["炽焰魔"] = { order = 8, type = "MOB", tips = "{rt8}炽焰魔{rt8}||{rt1}必断[爆炸烈焰]{rt1}，漏断全团AOE并叠可累加易伤；一波多只时排打断链或群控速杀" },
    ["漫游蜡烛"] = { order = 9, type = "MOB", tips = "{rt8}漫游蜡烛{rt8}||[镇火冲击]是30码硬吃全团AOE，可卡墙角/远程走远规避，近战提前减伤；躲[激涌烈焰]火圈并把怪带离火圈" },
    ["卑微的劳工"] = { order = 10, type = "MOB", tips = "{rt8}卑微的劳工{rt8}||老蜡须战中持续刷出，[粗制武器]叠层别硬吃；用矿车[高速碰撞]与[鲁莽冲锋]路径一次清光，被[诱引烛焰]点名时先风筝" },
}

-- ===================== 矶石宝库 (The Stonevault) =====================
addon.GuideData.versions["11.0"]["矶石宝库"] = {
    ["E.D.N.A."] = { order = 1, type = "BOSS", tips = "{rt8}E.D.N.A.{rt8}||分散站位；周期点名3人脚下生成[不稳定的尖刺]，躲开生成圈，任何人贴到4码内都会引爆(近身易秒)||[折光射线]一人一条拉开，用射线对准尖刺引爆，别1穿N；把场上尖刺控制在2根以内，否则[大地破裂]引爆全场伤害飙升，全员减伤||T对[震地猛击]减伤，随后[震地回响]DOT驱散会给T[大地之盾]减伤，全员帮驱" },
    ["斯卡莫拉克"] = { order = 2, type = "BOSS", tips = "{rt8}斯卡莫拉克{rt8}||[结晶猛击]打T后地上留紫圈并生成[水晶碎片]，{rt1}优先转火碎片{rt1}(T可把BOSS拉过去顺劈)，每颗存活的碎片都会给[崩解护壳]加盾；别同时炸多颗，注意减伤刷血||[无常碾压]躲BOSS身边大圈，随后地板圈生成黑色[虚空碎片]能量球，吃球对护盾+50%伤害并带DOT，血厚/有减伤的多吃||[回收]吸走剩余水晶成盾并开始[虚空释能]越A越疼，全爆发速破盾" },
    ["机械大师"] = { order = 3, type = "BOSS", tips = "{rt8}机械大师{rt8}||{rt1}两个必须同时死{rt1}，否则后死的会暴怒，全程修血||[代言人布洛克]：{rt1}必断[熔铁之水]{rt1}(全团AOE+减速)；[废料颂]跳到场边推泥头车横穿中场，绝对不要站中间直道||[代言人多利塔]：躲头前[熔岩排放]火球，T覆盖[熔岩之锤]减伤；[解体]把废料块拉到中央生成40码大火圈，站场地上/下两端躲爆炸与后续4道熔火波||[激活通风系统]四角激活三个，T把两只BOSS带到没喷火的那个排放口" },
    ["虚空代言人艾里克"] = { order = 4, type = "BOSS", tips = "{rt8}虚空代言人艾里克{rt8}||[熵能清算]点名所有人，结束脚下留黑水：全队集合叠着放以节省场地，然后一起离开||躲头前超大锥形[无拘虚空]，贴近BOSS更容易躲||{rt1}[虚空腐蚀]DOT每3秒+25%伤害，只有靠近[虚空绽放]裂隙15码内才能消除{rt1}；每消一次黑洞会移位，全队一起去同一个洞秒消，注意别被吸进3码内(瞬秒)，留位移跑路" },
    ["咒心入侵者"] = { order = 5, type = "MOB", tips = "{rt8}咒心入侵者{rt8}||{rt1}必断[恐惧咆哮]{rt1}(全团恐惧4秒)；[虚空感染]诅咒可叠加，群驱/单驱及时处理" },
    ["大地注能魔像"] = { order = 6, type = "MOB", tips = "{rt8}大地注能魔像{rt8}||[震地]全团AOE开减伤；躲头前[地震波]" },
    ["虚缚恐狼"] = { order = 7, type = "MOB", tips = "{rt8}虚缚恐狼{rt8}||[虚空风暴]6秒持续AOE，提前减伤，群控速杀" },
    ["被转化的代言人"] = { order = 8, type = "MOB", tips = "{rt8}被转化的代言人{rt8}||[禁声齿轮]单点沉默，有多余打断就断掉，别让治疗被沉默" },
    ["熔炉装货工"] = { order = 9, type = "MOB", tips = "{rt8}熔炉装货工{rt8}||躲头前火球；[熔岩迫击炮]点名高伤，被点名开减伤" },
    ["上进的铸手"] = { order = 10, type = "MOB", tips = "{rt8}上进的铸手{rt8}||[破碎打击]/[破裂]给坦克叠易伤，T开减伤，别硬吃多层" },
    ["炉铸愈疗者"] = { order = 11, type = "MOB", tips = "{rt8}炉铸愈疗者{rt8}||{rt1}必断[愈合金属]{rt1}(给友方回40%生命)" },
    ["击石者"] = { order = 12, type = "MOB", tips = "{rt8}击石者{rt8}||{rt1}重点集火目标{rt1}；[巨石碾压]全团AOE+击退，开减伤且别被推进危险区" },
    ["咒炉塑石者"] = { order = 13, type = "MOB", tips = "{rt8}咒炉塑石者{rt8}||{rt1}[爆地图腾]第一时间打掉{rt1}，不处理直接灭团" },
    ["咒炉荣誉卫兵"] = { order = 14, type = "MOB", tips = "{rt8}咒炉荣誉卫兵{rt8}||躲开蓝色冲撞路径；T对[裂石打击]开减伤" },
}

-- ===================== 千丝之城 (City of Threads) =====================
addon.GuideData.versions["11.0"]["千丝之城"] = {
    ["演说者基克斯威兹克"] = { order = 1, type = "BOSS", tips = "{rt8}演说者基克斯威兹克{rt8}||全程被[压迫之链]锁在BOSS脚下10码圈内，出圈超1秒会掉血并被拉回，不要试图跑出去||T对[压制](物理+暗影+减速)开减伤，本战压力主要在坦克||[喧神教化]4秒全团AOE后在BOSS脚下留不断扩大的[残存影响]黑水：贴墙放圈，结束后全队跟T统一方向移动||左右侧移躲[惊魂恫吓]锥形(命中恐惧4秒)；[疑之影]点名2人，被点者站定，结束射出5道球，{rt1}T绝不能吃球{rt1}(被晕极易倒T)" },
    ["女王之牙"] = { order = 2, type = "BOSS", tips = "{rt8}女王之牙{rt8}||每阶段只有一只能被T拉动，另一只自行跳位，T负责把两只叠到一起打||P1：躲[邃影斩]锥形并远离留下的[回响之影](会复制施法)，[暮落]要同时远离本体与影子各15码；[寒冰镰刀]点名多人，分散且飞行路径上不站人||满能量[协同步伐]双BOSS连续冲锋同一人，贴墙引导缩短位移，躲开交叉路径后转阶段||P2：[霜凝匕首]打T并给T叠[冰冻之血]，{rt1}全员立刻进T脚下白圈帮分摊层数{rt1}，叠满会把T冻住直接灭团" },
    ["凝结聚合体"] = { order = 3, type = "BOSS", tips = "{rt8}凝结聚合体{rt8}||[粘稠黑暗]击退全员并从四周容器放出[黑血之球]朝BOSS移动，{rt1}必须在场边把球全部撞掉{rt1}，被BOSS吃到每颗回血||撞球会得吸收治疗的debuff并叠层，一人约2颗，别贪多||T对[溢流猛击](-30%受疗)开减伤；[血之激涌]读条时近战跑出8码并躲开脚下黑血||能量满[黑暗脉动]全团AOE，减伤+爆发治疗；除T以外都尽量远离BOSS" },
    ["大捻接师艾佐"] = { order = 4, type = "BOSS", tips = "{rt8}大捻接师艾佐{rt8}||场上3颗[变易异常]法球每9秒换位，看落点圈提前躲，别站飞行路径，T带着BOSS往后退||[捻接]全团持续暗影DOT，读出即铺减伤与团刷||[震颤猛击]化身蛛魔领主砸地，12码内额外巨伤，近战快跑开；随后{rt1}[贪婪的甲虫]第一时间群控+转火{rt1}(啃5次会爆炸并昏迷4秒)||[晦幽纺纱]全员被网定身12秒，集合站位速破网；紧接[汰劣程序]召回所有法球逐个碾爆，近战跑出10码、T开大减伤" },
    ["皇家虫群卫士"] = { order = 5, type = "MOB", tips = "{rt8}皇家虫群卫士{rt8}||[贪婪之虫]群体DOT持续6秒；躲头前锥形[裂地猛击]" },
    ["苏雷吉缚丝者"] = { order = 6, type = "MOB", tips = "{rt8}苏雷吉缚丝者{rt8}||{rt1}必断[流丝缠缚]{rt1}(束缚并持续掉血，引导完成会昏迷)；[蛛网箭]有余力就断" },
    ["苏雷吉剧毒之刃"] = { order = 7, type = "MOB", tips = "{rt8}苏雷吉剧毒之刃{rt8}||[剧毒之刃]打T直伤+中毒，本副本驱毒优先级最高，及时驱" },
    ["安苏雷克的传令官"] = { order = 8, type = "MOB", tips = "{rt8}安苏雷克的传令官{rt8}||{rt1}必断[扭曲思绪]{rt1}(点名高伤)；[疑之影]先出人群再驱散，躲开射出的5道方向波" },
    ["谢非提克"] = { order = 9, type = "MOB", tips = "{rt8}谢非提克{rt8}||取信息素找奸细的关键战：断[蛛网箭]，躲[香水投掷]点名地板与[纱网弹幕]" },
    ["女王之牙"] = { order = 10, type = "BOSS", tips = "{rt8}女王之牙{rt8}||3只奸细逐个击杀：躲[虚无猛击](消失后跳到身后放头前地板)；[虚空奔袭]点名物理直伤+法伤DOT，覆盖减伤" },
    ["掠网者"] = { order = 11, type = "MOB", tips = "{rt8}掠网者{rt8}||打T技能附带10%增伤持续30秒，T注意叠层与减伤衔接" },
    ["隐秘网士"] = { order = 12, type = "MOB", tips = "{rt8}隐秘网士{rt8}||{rt1}必断[隐秘冲击]与[治愈之网]{rt1}(前者会在玩家间弹射，后者引导回血)" },
    ["敏捷的追击者"] = { order = 13, type = "MOB", tips = "{rt8}敏捷的追击者{rt8}||随机点名飞刀物理伤害，血线偏低时注意自保，可控可打断" },
}

-- ===================== 艾拉-卡拉，回响之城 (Ara-Kara, City of Echoes) =====================
addon.GuideData.versions["11.0"]["艾拉-卡拉，回响之城"] = {
    ["阿瓦诺克斯"] = { order = 1, type = "BOSS", tips = "{rt8}阿瓦诺克斯{rt8}||需先清掉[伊克辛]/[纳克特]/[阿提克]三只门神小BOSS才会出现||[警示尖鸣]3秒持续AOE伤害极高，提前铺团减；同时从卵中孵出[饥饿爬蛛]，{rt1}第一时间控住并转火，绝不能带到BOSS近战位{rt1}——被吞掉会触发[贪得无厌]永久+50%增伤且可叠加||[蛛纱强袭]5秒AOE且每人脚下追着放[邪恶缠网]，全队集合朝同一方向走以节省场地，缠网叠10层变[裹体之网]瘫痪10秒||T对[贪食撕咬](3连击+50%易伤)开减伤" },
    ["阿努布泽克特"] = { order = 2, type = "BOSS", tips = "{rt8}阿努布泽克特{rt8}||T让BOSS背对队友，[穿刺]是朝当前目标的长锥形||被[感染]点名开减伤，结束会在原地留[无休虫群]，尽量把它丢到场外；躲开场上游走的紫圈(叠[溃烂创伤])||[钻地冲击]离BOSS越远越好躲，别站在他钻出的落点圈里，出土后紧接一段长锥形||召唤的[染血的网法师]{rt1}速杀并断[流丝束缚]{rt1}||满能量[虫群之眼]全场被虫群覆盖，进入移动的白色安全圈，此阶段更要防[穿刺]与[感染]" },
    ["收割者吉卡塔尔"] = { order = 3, type = "BOSS", tips = "{rt8}收割者吉卡塔尔{rt8}||[毒液浸雨]与[培植毒药]群体中毒DOT，{rt1}优先驱毒{rt1}；[培植毒药]结束会从每人身上向两侧射出毒液波，务必分散且不要对着队友||躲[爆发蛛网]地板圈||[血工]受伤会抛下黑血，踩到[抓握之血]定身1分钟，对黑血小怪控/断即可解救||{rt1}[宇宙奇点]把全队拖向BOSS，读条结束前必须离开脚下圈否则瞬秒{rt1}——没位移就提前踩黑水把自己定住，或最后一刻用位移跳出" },
    ["伊克辛"] = { order = 4, type = "MOB", tips = "{rt8}伊克辛{rt8}||{rt1}必断[恐惧尖鸣]{rt1}(全队恐惧6秒)；躲头前[蛛网喷射]锥形；[蛛网箭]能断就断" },
    ["纳克特"] = { order = 5, type = "MOB", tips = "{rt8}纳克特{rt8}||[巢穴的召唤]不可打断的高伤AOE且读条很快，{rt1}必须提前开团减/个人减伤{rt1}；躲头前[蛛网喷射]" },
    ["阿提克"] = { order = 6, type = "MOB", tips = "{rt8}阿提克{rt8}||[毒液箭]只打T；躲开[毒云]绿圈与头前[蛛网喷射]锥形" },
    ["颤声侍从"] = { order = 7, type = "MOB", tips = "{rt8}颤声侍从{rt8}||{rt1}必断[共振弹幕]{rt1}(高额全团AOE)；[蛛网箭]有余力再断，T开火车时别浪费控制在它身上" },
    ["充血的爬行者"] = { order = 8, type = "MOB", tips = "{rt8}充血的爬行者{rt8}||[毒性喷涂]中毒卡CD驱散；残血读[剧毒崩裂]自爆，用群控链错开引爆时机并远离绿圈" },
    ["魁梧的血卫"] = { order = 9, type = "MOB", tips = "{rt8}魁梧的血卫{rt8}||{rt1}在场时作为主目标优先击杀{rt1}(给周围友方光环)；躲[穿刺]锥形与[野蛮猛击](AOE+晕1秒)，[烈度]每层+10%伤害" },
    ["沾血的网法师"] = { order = 10, type = "MOB", tips = "{rt8}沾血的网法师{rt8}||{rt1}必断[恶臭齐射]{rt1}，漏断会给全团上疼痛DOT；[蛛网箭]可选断" },
    ["哨兵鹿壳虫"] = { order = 11, type = "MOB", tips = "{rt8}哨兵鹿壳虫{rt8}||{rt1}[预警尖鸣]10秒长读条必须控断{rt1}，漏断灭团风险极高；每10秒一次，安排控制链" },
    ["沾血的助手"] = { order = 12, type = "MOB", tips = "{rt8}沾血的助手{rt8}||[深掘打击]打T，命中会给自己回血并增伤，T尽量躲或开减伤" },
    ["鲜血监督者"] = { order = 13, type = "MOB", tips = "{rt8}鲜血监督者{rt8}||{rt1}必断[毒液箭雨]{rt1}(高伤AOE+DOT)；躲开[爆发蛛网]地板" },
    ["蛛魔搬运者"] = { order = 14, type = "MOB", tips = "{rt8}蛛魔搬运者{rt8}||躲头前[穿刺]锥形与[野蛮猛击](晕1秒)；[烈度]叠层增伤，优先集火压掉" },
    ["飞翼运输者"] = { order = 15, type = "MOB", tips = "{rt8}飞翼运输者{rt8}||落地会留[黑血]黑水，别踩；[冲锋]随机点名，注意躲开路径" },
}

-- ===================== 破晨号 (The Dawnbreaker) =====================
addon.GuideData.versions["11.0"]["破晨号"] = {
    ["代言人夏多克朗"] = { order = 1, type = "BOSS", tips = "{rt8}代言人夏多克朗{rt8}||T把BOSS尽量拉离黑水区，方便之后躲射线||[黑曜光束]先高额打T(必开减伤)，随后3-4道直线激光开始旋转，跟着一起转圈躲，闪现类穿不过去||[塌缩之夜]点名远程，脚下生成逐渐扩大的黑水，点名前就远离BOSS把水放远||[燃烧之影]点名DOT+减速{rt1}优先驱散{rt1}，驱散后给4人[暗影之幕]吸收盾，治疗速刷掉；尽量断[暗影箭]||{rt1}50%与1%读[黑暗降临]时立刻上飞行坐骑飞出船外{rt1}(留在船上必死)，在外面吃[圣光残片]维持[光芒四射]，读完再飞回；别带着吸收盾出去" },
    ["阿努布伊卡基"] = { order = 2, type = "BOSS", tips = "{rt8}阿努布伊卡基{rt8}||{rt1}开BOSS前必须先分别清掉3名副官{rt1}[扬升者维斯可里亚]/[死亡尖啸者艾肯塔克]/[坚不可摧的伊克斯雷腾]，否则BOSS带[强化力量]||[暗黑法球]点名有紫色连线，被点者背对空旷方向(往过道引)让球飞得越远越好，伤害随飞行距离降低，别碰球||[晦影腐朽]3秒全团高伤AOE，交团减||T被[恐惧猛击]击退且周围队友被恐惧，T靠墙站、其他人远离T脚下大紫圈||[活化暗影]召出软泥，被点名者靠近T让T接怪，群控一起A掉；BOSS死后小怪不会消失，也要清完" },
    ["拉夏南"] = { order = 3, type = "BOSS", tips = "{rt8}拉夏南{rt8}||P1：躲[缠网喷吐]两条直线；[酸液翻腾]看自己左右哪侧是浅绿，朝那侧把波浪甩向没人的地方(命中会昏迷)；[侵蚀喷涌]2秒全团AOE+叠加DOT，减伤并驱散||{rt1}捡起[阿拉希炸弹]贴到BOSS近战范围扔出{rt1}，吃满6颗转阶段；拿着超时会给全团上DOT||转阶段跟着与你连线的燃灯者小舟飞，路上尽量吃[圣光残片]，不吃球约24秒后必死||P2：[喷射丝线]点名2人，远离BOSS与人群放大圈，被拴住后拉开会[喷丝网裂]全团AOE，开减伤；用[酸液翻腾]的波把地上[粘性蛛网]烧成[酸液池]清场，注意别踩||近战范围没人会触发[粘稠迸发]" },
    ["夜幕司令官"] = { order = 4, type = "MOB", tips = "{rt8}夜幕司令官{rt8}||{rt1}必断[深渊嚎叫]{rt1}(给周围小怪加盾并AOE)；[污邪打击]打T流血，T注意减伤" },
    ["夜幕影法师"] = { order = 5, type = "MOB", tips = "{rt8}夜幕影法师{rt8}||{rt1}必断[诱捕暗影]{rt1}(高伤+诅咒DOT+减速)，没断成功就驱诅咒；[暗夜箭]有余力就断" },
    ["夜幕咒刃"] = { order = 6, type = "MOB", tips = "{rt8}夜幕咒刃{rt8}||[黑暗之刃]打T并给自己叠攻速，T注意层数与减伤衔接" },
    ["夜幕祭师"] = { order = 7, type = "MOB", tips = "{rt8}夜幕祭师{rt8}||[折磨光束]随机点名2人DOT，开减伤；[冥河之种]点名魔法DOT要驱散，会炸8码，先出人群再驱" },
    ["苏雷吉网法师"] = { order = 8, type = "MOB", tips = "{rt8}苏雷吉网法师{rt8}||[迸发虫茧]点名后周围有白圈，其他人别进，被点者6秒内出人群+减伤+驱散；[蛛网箭]只打T，看情况断" },
    ["暗影具象"] = { order = 9, type = "MOB", tips = "{rt8}暗影具象{rt8}||[深渊朽烂]点名8秒DOT；躲[黑暗之雾]紫色地板圈；残血后开始[黑暗潮涌]5秒全团AOE，开减伤" },
    ["夜幕影行者"] = { order = 10, type = "MOB", tips = "{rt8}夜幕影行者{rt8}||[暗影突击]高额打T，T一定开减伤" },
    ["夜幕战略家"] = { order = 11, type = "MOB", tips = "{rt8}夜幕战略家{rt8}||躲开头前[黑刃之锋]紫色锥形地板" },
    ["夜幕黑暗建筑师"] = { order = 12, type = "MOB", tips = "{rt8}夜幕黑暗建筑师{rt8}||{rt1}[折磨喷发]点名2人以自身为中心AOE，伤害极高，全程分散站位{rt1}，同时吃到两个必死；[招引增援]召出数个咒刃与影法师，断好[诱捕暗影]" },
}

-- ===================== 水闸行动 (Operation: Floodgate，原 11.1 合并) =====================
addon.GuideData.versions["11.0"]["水闸行动"] = {
    ["老大娘"] = { order = 1, type = "BOSS", tips = "{rt8}老大娘{rt8}||速杀4台[暗索机械无人机]触发[快速启动]易伤;MUST NOT让本体开[夺命封锁屏障](-80%减伤+全团AOE){rt1}必断无人机[终极失真]{rt1}||[音爆]被点名朝场外引,撞墙7码爆炸击退沉默;[电气重碾]坦开减伤||[毁灭风暴]直线躲开;易伤结束留[超量电化]电水,拉边打保场地" },
    ["撕碎王3000型"] = { order = 2, type = "MOB", tips = "{rt8}撕碎王3000型{rt8}||[碎切]读条结束每人脚下出电锯,读条一停立刻侧移躲第一跳||[火焰喷射器]顺时针/逆时针转圈头前喷火,躲头前且别站地板锯齿" },
    ["无人机狙击手"] = { order = 3, type = "MOB", tips = "{rt8}无人机狙击手{rt8}||{rt1}必断[特技射击]{rt1}3秒读条出法术AOE弹射,高层漏断易团灭||平砍[狙击]随机点名疼,被盯开减伤;不吃控可拉断/晕断" },
    ["风险投资公司勘探员"] = { order = 4, type = "MOB", tips = "{rt8}风险投资公司勘探员{rt8}||{rt1}断[勘测光束]{rt1}引导减速并在脚下留岩浆池,点完即跑开||[易投炸弹]躲落点别踩雷;周围[土狼]嗜血狞笑可断/驱激怒" },
    ["破拆双人组"] = { order = 5, type = "BOSS", tips = "{rt8}破拆双人组{rt8}||双子修血一起死!单死触发[天人永隔]另一方每4秒+20%伤||布隆特[滚桶冲锋]路径穿炸弹清雷(前两发随机后一发必中坦);被点[动能胶质炸药]提前站炸弹上再由奶驱散引爆{rt1}[天降神雷]炸弹30秒到期全团AOE,靠冲锋/凝胶清{rt1}||[重击]坦开减伤、[B.B.B.F.G.]躲射线、[快速射击]随机疼" },
    ["暗索扭血者"] = { order = 6, type = "MOB", tips = "{rt8}暗索扭血者{rt8}||{rt1}必断[噬血箭]{rt1}漏断易秒坦||[扭曲鲜血]全团吸奶盾无法卡视野,治疗预铺+全队减伤硬奶;别拉太高层" },
    ["风险投资公司建筑师"] = { order = 7, type = "MOB", tips = "{rt8}风险投资公司建筑师{rt8}||先拆[脚手架]否则建筑师近乎无敌||[射钉枪]定身+流血,自由/解定身解掉,别同时拉两只以上防combo" },
    ["风险投资公司潜水员"] = { order = 8, type = "MOB", tips = "{rt8}风险投资公司潜水员{rt8}||[爆盐炸弹]地上种雷躲开别踩||[鱼叉]拉人+流血可驱散,被勾开减伤" },
    ["沼面"] = { order = 9, type = "BOSS", tips = "{rt8}沼面{rt8}||[割喉藤蔓]两两捆绑,超14码被拉回,配对一起走(通常顺时针)||[泥石流]头前躲、[汹涌怒涛]波浪推开、[唤醒沼泽]全团减伤||坦[淤泥之爪]吸奶开减伤,治疗全技能预铺" },
    ["被惊扰的海藻"] = { order = 10, type = "MOB", tips = "{rt8}被惊扰的海藻{rt8}||{rt1}必断[投弃海藻]{rt1}钢条全团AOE,群控只昏迷可断,慢则减员||[恢复]治疗可驱/断,留全套爆发快速融掉防控制链断" },
    ["吉泽尔·超震"] = { order = 11, type = "BOSS", tips = "{rt8}吉泽尔·超震{rt8}||[涡轮增压]回原位放[涡轮霹雳]光束,躲[水坝碎石]落石与[水坝渗流]水洼||[激荡之水]带电水面勿踩(昏迷4秒);[跃动火花]引去干净水洼再扩散{rt1}必断[超力震击]类电DOT{rt1}||[雷霆重拳]击退坦开减伤、[火花猛击]坦正面重击开减伤" },
    ["风险投资公司电工"] = { order = 12, type = "MOB", tips = "{rt8}风险投资公司电工{rt8}||{rt1}必断[闪电箭]{rt1}两发直秒人||[过载]魔法DOT不驱散会晕5秒,秒驱(类似驱1刷1)" },
    ["暗索调查员"] = { order = 13, type = "MOB", tips = "{rt8}暗索调查员{rt8}||[突击调查]闪现到玩家背后放锥形头前,怪多看不见紫色特效要小心||可用控制断钢条,被点名躲开队友防combo" },
}
